#!/usr/bin/env python3
'''Standalone finite-grammar check for K-ALG-012.

This is a CPU logic check. It does not measure GPU behavior.
'''
PRODUCTIONS = {
    'S': (('[', 'E', ']'),),
    'E': ((), ('V',), ('V', ',', 'V')),
    'V': (('a',), ('b',), ('[', 'F', ']')),
    'F': ((), ('W',), ('W', ',', 'W')),
    'W': (('a',), ('b',)),
}
ALPHABET = frozenset('[]ab,')

def epsilon_closure(stacks):
    work = [tuple(s) for s in stacks]
    out = set()
    while work:
        st = work.pop()
        if st in out:
            continue
        out.add(st)
        if st and st[-1] in PRODUCTIONS:
            top = st[-1]
            base = st[:-1]
            for prod in PRODUCTIONS[top]:
                new = base + tuple(reversed(prod))
                if new not in out:
                    work.append(new)
    return frozenset(out)

def advance(states, text):
    cur = frozenset(states)
    for ch in text:
        nxt = set()
        for st in cur:
            if st and st[-1] == ch:
                nxt.add(st[:-1])
        cur = epsilon_closure(nxt)
        if not cur:
            return frozenset()
    return cur

INITIAL = epsilon_closure({('S',)})

def eos_ok(states):
    return () in states

def pda_legal(prefix, token):
    after_prefix = advance(INITIAL, prefix)
    return bool(advance(after_prefix, token))

def gen_W():
    yield 'a'
    yield 'b'

def gen_F():
    yield ''
    for w in gen_W():
        yield w
        for w2 in gen_W():
            yield w + ',' + w2

def gen_V():
    yield 'a'
    yield 'b'
    for f in gen_F():
        yield '[' + f + ']'

def gen_E():
    yield ''
    for v in gen_V():
        yield v
        for v2 in gen_V():
            yield v + ',' + v2

def gen_S():
    for e in gen_E():
        yield '[' + e + ']'

ACCEPTED = frozenset(gen_S())
PREFIXES = frozenset(s[:i] for s in ACCEPTED for i in range(len(s) + 1))
TOKENS = ('[', ']', 'a', 'b', ',', '[]', '[a', 'a]', ']]', 'a,]', 'a,', '[[a', 'a,b]', ']]]', 'b]]', '[')

def ref_legal(prefix, token):
    needle = prefix + token
    return any(s.startswith(needle) for s in ACCEPTED)

def first_char_only(prefix, token):
    return bool(token) and token[0] in ALPHABET

def restricted_distribution(probs, legal):
    if not legal:
        raise ValueError('empty legal set')
    z = sum(probs[t] for t in legal)
    if z <= 0.0:
        raise ValueError('zero legal mass')
    return {t: (probs[t] / z if t in legal else 0.0) for t in probs}

def main():
    mismatches = []
    for p in sorted(PREFIXES):
        for t in TOKENS:
            expected = ref_legal(p, t)
            observed = pda_legal(p, t)
            if expected != observed:
                mismatches.append((p, t, expected, observed))
    if mismatches:
        print('PDA/reference mismatches:', len(mismatches))
        for item in mismatches[:5]:
            print('  prefix=%r token=%r expected=%r observed=%r' % item)
        raise AssertionError('PDA mask does not match finite-language oracle')
    print('observations: accepted=%d prefixes=%d tokens=%d compared=%d' % (len(ACCEPTED), len(PREFIXES), len(TOKENS), len(PREFIXES) * len(TOKENS)))

    eos_bad = []
    for p in sorted(PREFIXES):
        expected = p in ACCEPTED
        observed = eos_ok(advance(INITIAL, p))
        if expected != observed:
            eos_bad.append((p, expected, observed))
    if eos_bad:
        print('EOS mismatches:', len(eos_bad))
        for item in eos_bad[:5]:
            print('  prefix=%r expected=%r observed=%r' % item)
        raise AssertionError('EOS legality does not match accepting prefixes')
    print('eos checks:', len(PREFIXES))

    probes = (('[a', ']]'), ('[[a', ']]'), ('[', 'a,]'), ('[', 'a,b]'), ('[]', ']'))
    for p, t in probes:
        print('probe prefix=%r token=%r reference=%s pda=%s first_char=%s' % (p, t, ref_legal(p, t), pda_legal(p, t), first_char_only(p, t)))

    if not (ref_legal('[a', ']]') is False):
        raise AssertionError('reference should reject [a + ]]')
    if not (pda_legal('[a', ']]') is False):
        raise AssertionError('PDA should reject [a + ]]')
    if not (first_char_only('[a', ']]') is True):
        raise AssertionError('negative control should accept [a + ]] by first char')
    if not (ref_legal('[[a', ']]') is True):
        raise AssertionError('reference should accept [[a + ]]')
    if not (pda_legal('[[a', ']]') is True):
        raise AssertionError('PDA should accept [[a + ]]')

    bad = []
    for p in sorted(PREFIXES):
        for t in TOKENS:
            expected = ref_legal(p, t)
            observed = first_char_only(p, t)
            if expected != observed:
                bad.append((p, t, expected, observed))
    if not bad:
        raise AssertionError('first-char negative control was not detected')
    print('first-char negative control disagreements:', len(bad))
    print('  first disagreement prefix=%r token=%r reference=%s faulty=%s' % bad[0])

    probs = {'a': 0.4, 'b': 0.3, 'c': 0.2, 'd': 0.1}
    legal = frozenset(('a', 'c'))
    masked = restricted_distribution(probs, legal)
    if masked['b'] != 0.0 or masked['d'] != 0.0:
        raise AssertionError('illegal token kept probability')
    if abs(masked['a'] - (0.4 / 0.6)) > 1e-12:
        raise AssertionError('legal probability ratio changed')
    if abs(sum(masked.values()) - 1.0) > 1e-12:
        raise AssertionError('masked distribution was not normalized')
    print('masked distribution sum: %.12f' % sum(masked.values()))

    try:
        restricted_distribution(probs, frozenset())
    except ValueError:
        print('empty legal set: rejected as protocol failure')
    else:
        raise AssertionError('empty legal set was not rejected')

    print('PASS: finite-language mask, EOS, empty-set failure, and negative control')

if __name__ == '__main__':
    main()
